{
  "contract": "KatRoyalties",
  "closure": {
    "site_function": "withdraw",
    "site_call": ".call",
    "functions": [
      "spin",
      "withdraw"
    ],
    "justification": "These functions interact with the exposed storage variables 'balances', 'winnerFunds', and 'withdrawing'."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "spin"
    ],
    "nesting_bound": {
      "withdraw": 1
    }
  },
  "phases": {
    "function": "withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of balances in transit during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_balances == winnerFunds + inFlight",
    "stable_formula": "_sum_balances == winnerFunds",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_balances == winnerFunds",
    "rule": "The exposure invariant ensures that the sum of balances is conserved across the callback window, accounting for in-flight transfers."
  }
}
